import 'dart:convert';import 'package:http/http.dart'as http;
class ApiService{String baseUrl=const String.fromEnvironment('XAI_API_URL',defaultValue:'http://localhost:8000');String?token;Future<void>login(String email,String password,{String?totp})async{final r=await http.post(Uri.parse('$baseUrl/auth/login'),headers:{'content-type':'application/json'},body:jsonEncode({'email':email,'password':password,'totp_code':totp}));if(r.statusCode>=400)throw Exception(r.body);token=jsonDecode(r.body)['access_token'];}Future<List<dynamic>>history()async{final r=await http.get(Uri.parse('$baseUrl/history'),headers:{'authorization':'Bearer $token'});if(r.statusCode>=400)throw Exception(r.body);return jsonDecode(r.body);}Future<Map<String,dynamic>>redeem(String code)async{final r=await http.post(Uri.parse('$baseUrl/shares/redeem'),headers:{'content-type':'application/json','authorization':'Bearer $token'},body:jsonEncode({'code':code}));if(r.statusCode>=400)throw Exception(r.body);return Map<String,dynamic>.from(jsonDecode(r.body));}}
